import dimensions from "@/lib/content/photo-dimensions.json";

/** Pixel size of every source photo, keyed by R2 key ("rooms/rooms_76.jpg"). Generated by scripts/photo-dimensions.ts. */
export const PHOTO_DIMENSIONS: Record<string, { w: number; h: number }> = dimensions;

/** Sharpness rule: source must be at least `tolerance` x the display slot in BOTH dimensions. Unknown key: false. */
export function photoFits(key: string, slot: { w: number; h: number }, tolerance = 1.5): boolean {
  const src = PHOTO_DIMENSIONS[key];
  if (!src) return false;
  return src.w >= slot.w * tolerance && src.h >= slot.h * tolerance;
}

/** Largest display height (rounded down) that still fits at `slotWidth`; 0 if unknown or the width alone is too large. */
export function maxSlotHeight(key: string, slotWidth: number, tolerance = 1.5): number {
  const src = PHOTO_DIMENSIONS[key];
  if (!src || src.w < slotWidth * tolerance) return 0;
  return Math.floor(src.h / tolerance);
}

/**
 * Height for a cover-fit frame `slotWidth` wide: the sharp maximum (`maxSlotHeight`), capped at the frame's own
 * design maximum `cap`. 0 means the source cannot fill this slot sharply; put it in a smaller slot.
 */
export function frameHeight(key: string, slotWidth: number, cap: number, tolerance = 1.5): number {
  const h = maxSlotHeight(key, slotWidth, tolerance);
  return h === 0 ? 0 : Math.min(cap, h);
}

/**
 * The largest sharp frame for `key` in a slot `slotWidth` wide with design height maximum `cap`:
 * `maxW` = source.w / tolerance (never display wider), `h` = min(cap, source.h / tolerance), and `fits` = whether the
 * source can fill the whole slot width. null for an unknown key.
 */
export function frameBox(key: string, slotWidth: number, cap: number, tolerance = 1.5): { fits: boolean; maxW: number; h: number } | null {
  const src = PHOTO_DIMENSIONS[key];
  if (!src) return null;
  const maxW = Math.floor(src.w / tolerance);
  return { fits: maxW >= slotWidth, maxW, h: Math.min(cap, Math.floor(src.h / tolerance)) };
}
